------------ import ------------
------------ import ------------

------------ define ------------
local KTool = CS.Engine.Lib.KTool
local BehaviourAction = CS.Engine.Lib.BehaviourAction
local Light = CS.UnityEngine.Light
local XLuaUtils = CS.Engine.Lib.XLuaUtils
------------ define ------------

---@class HomeCharaLight
local HomeCharaLight = Class('HomeCharaLight')

function HomeCharaLight:__init()
    self._behaviorAction = nil
    self._roleRoot = nil
    self._cultivateRoot = nil
    self.skinId = nil
    ---@type UnityEngine.Light
    self.light = nil
    self.isOverwriting = false
end

function HomeCharaLight:__delete()
    self._behaviorAction = nil
    self._roleRoot = nil
    self._cultivateRoot = nil
    self.skinId = nil
    self.light = nil
    self.isOverwriting = false
end

function HomeCharaLight:Awake()
    ---@type CardProgressionUtils
    local CardProgressionUtils = import("Game.CardProgression.CardProgressionUtils")
    ---@type CardProgressionControllerRole
    local env = CardProgressionUtils.GetRoleControllerEnv()
    self._roleRoot = env:GetRoleRoot()
    if isNotNull(self._roleRoot) then
        self._cultivateRoot = self._roleRoot.transform.parent.parent
    end
    self.light = KTool.GetComponent(self.controller.gameObject, typeof(Light))

    local IsActive = CfUtils.IsActive
    ---SetLightColor
    ---@param light UnityEngine.Light
    ---@param color string
    local function SetLightColor(light, color, intensity)
        if isNotNull(light) then
            light.color = XLuaUtils.HexToColor(color)
            light.intensity = checkNumber(intensity)
        end
    end

    local cardConfMgr = CardConfMgr:GetInstance()
    ---@type Engine.Lib.BehaviourAction
    local behaviorAction = KTool.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
    behaviorAction.UpdateAction = function()
        xTry(function()
            if isNotNull(self._roleRoot) and isNotNull(self._cultivateRoot) and isNotNull(env) and isNotNull(self.controller) then
                if IsActive(self.controller.gameObject) then
                    if IsActive(self._roleRoot) and IsActive(self._cultivateRoot) then
                        local cardSkinId = env:GetRoleSkinId()
                        --local catSkinId = env:GetCatSkinId()
                        if self.isOverwriting or (not isNull(cardSkinId) and self.skinId ~= cardSkinId) then
                            self.skinId = cardSkinId
                            local skinVo = cardConfMgr:GetCardSkinBySkinId(cardSkinId, true)
                            if skinVo then
                                --print("===>>", cardSkinId, skinVo.color)
                                local color = string.isEmpty(skinVo.color) and 'ffffff' or skinVo.color
                                SetLightColor(self.light, '#' .. color, skinVo.intensity)
                            end
                        end
                        self.isOverwriting = false

                    else
                        ---不显示的情况下，直接重置回
                        if not self.isOverwriting then
                            self.isOverwriting = true
                            SetLightColor(self.light, "#ffffff", 0.9)
                        end
                    end
                end
            end
        end)
    end
    self._behaviorAction = behaviorAction
end

function HomeCharaLight:OnDestroy()
    if not isNull(self._behaviorAction) then
        self._behaviorAction.UpdateAction = nil
    end
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return HomeCharaLight